{"command": "cd /home/user/rork-app/expo && cat > /tmp/ivx_audit.py << 'PYEOF'
import os, re, json

app_dir = 'app'
screens = []

for root, dirs, files in os.walk(app_dir):
    for f in sorted(files):
        if not f.endswith('.tsx') or '_layout' in f or '__tests__' in root:
            continue
        if f.startswith('+') or '/api/' in os.path.join(root, f):
            continue
        filepath = os.path.join(root, f)
        relpath = filepath
        try:
            with open(filepath, 'r') as fh:
                content = fh.read()
        except:
            continue

        has_loading = bool(re.search(r'isLoading|loading|Skeleton|ShimmerIndicator|ActivityIndicator|IVXDataProvider', content))
        has_error = bool(re.search(r'error|Error|catch|isError', content))
        has_flatlist = bool(re.search(r'FlatList', content))
        has_pagination = bool(re.search(r'onEndReached|useInfiniteQuery|fetchNextPage|loadMore|hasMore', content))
        has_usequery = bool(re.search(r'useQuery\(', content))
        has_supabase = bool(re.search(r'supabase\.from\(', content))
        has_fetch = bool(re.search(r'fetch\(', content))
        has_realtime = bool(re.search(r'useRealtime|channel\(|postgres_changes', content))
        has_ivximage = bool(re.search(r'IVXImage|CachedImage|ControlledImage|OptimizedImage', content))
        has_rawimage = bool(re.search(r'<Image\b|expo-image|source.*uri', content))
        has_empty = bool(re.search(r'empty|Empty|no.*data|no.*content|no.*results', content, re.I))
        has_refresh = bool(re.search(r'RefreshControl|refetch|onRefresh|pull.*refresh', content, re.I))

        issues = []
        if not has_loading: issues.append('NO_LOADING')
        if not has_error: issues.append('NO_ERROR')
        if has_flatlist and not has_pagination: issues.append('NO_PAGINATION')
        if has_rawimage and not has_ivximage: issues.append('RAW_IMAGE')
        if not has_realtime: issues.append('NO_REALTIME')
        if not has_empty: issues.append('NO_EMPTY_STATE')
        if not has_refresh: issues.append('NO_REFRESH')

        status = 'PASS' if len(issues) == 0 else ('FAIL' if len(issues) <= 3 else 'CRITICAL')

        screens.append({
            'route': relpath,
            'issues': issues,
            'status': status,
            'hasUseQuery': has_usequery,
            'hasSupabase': has_supabase,
            'hasFetch': has_fetch,
            'hasFlatList': has_flatlist,
        })

screens.sort(key=lambda s: s['route'])

pass_count = sum(1 for s in screens if s['status'] == 'PASS')
fail_count = sum(1 for s in screens if s['status'] == 'FAIL')
critical_count = sum(1 for s in screens if s['status'] == 'CRITICAL')

print(f"Total screens: {len(screens)}")
print(f"PASS: {pass_count}")
print(f"FAIL: {fail_count}")
print(f"CRITICAL: {critical_count}")
print()

issue_counts = {}
for s in screens:
    for issue in s['issues']:
        issue_counts[issue] = issue_counts.get(issue, 0) + 1
for issue, count in sorted(issue_counts.items(), key=lambda x: -x[1]):
    print(f"  {issue}: {count} screens")
print()

print("=== CRITICAL screens (4+ issues) ===")
for s in screens:
    if s['status'] == 'CRITICAL':
        print(f"  {s['route']}: {', '.join(s['issues'])}")

print()
print("=== FAIL screens (1-3 issues) ===")
for s in screens:
    if s['status'] == 'FAIL':
        print(f"  {s['route']}: {', '.join(s['issues'])}")

# Save as JSON
with open('/tmp/ivx_screen_audit.json', 'w') as f:
    json.dump(screens, f, indent=2)
print(f"\nFull audit saved to /tmp/ivx_screen_audit.json")
PYEOF
python3 /tmp/ivx_audit.py"}

